using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.Network.WebSocket;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server    _server;
		private          TcpClient _client;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
		}

		public EndPoint GetEndPoint()
			=> _client.Client.RemoteEndPoint;

		public bool IsConnected()
			=> _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_client.Close();
				_client = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer()
			=> _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			var payload = new JObject {
				["event"] = ev,
				["args"]  = new JArray(args)
			};

			var str    = payload.ToString(Formatting.None);
			var buffer = Encoding.UTF8.GetBytes(str);



		}
	}
}

using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server _server;
		private TcpClient _client;
		private NetworkStream _stream;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
			_stream = _client.GetStream();
		}

		public EndPoint GetEndPoint() => _client?.Client?.RemoteEndPoint;

		public bool IsConnected() => _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_stream?.Close();
				_client?.Close();
				_client = null;
				_stream = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer() => _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			try {
				var payload = new JObject {
					["event"] = ev,
					["args"] = new JArray(args)
				};

				var str = payload.ToString(Formatting.None);
				var buffer = Encoding.UTF8.GetBytes(str + "\n");

				await _stream.WriteAsync(buffer, 0, buffer.Length);
			} catch (Exception ex) {
				Logger.LogError($"Error sending data to client {GetEndPoint()}: {ex.Message}");
			}
		}
	}
}

using System;
using Nox.CCK.Network;
using Nox.Entities;

namespace api.nox.relay {
	public class RawRelayProperty : RelayProperty {
		private readonly string        _key;
		private          object        _value;
		private          DirtyBy       _dirty;
		private          PropertyFlags _flags;

		public RawRelayProperty(RelayPlayer player, string key, object value) : base(player) {
			if (string.IsNullOrEmpty(key))
				throw new ArgumentException("Property key cannot be null or empty", nameof(key));
			_key = key;
			_value = value
				?? throw new ArgumentNullException(nameof(value), "Property value cannot be null");
		}

		public override string GetKey()
			=> _key;

		public override object GetValue()
			=> _value;

		public override PropertyFlags GetFlags()
			=> _flags;

		public override void SetValue(object value, DirtyBy by) {
			_value = value;
			SetDirty(by);
		}

		public override byte[] Serialize() {
			try {
				return _value.ToBytes();
			} catch (Exception e) {
				throw new InvalidOperationException($"Failed to serialize property '{_key}'", e);
			}
		}

		public override void Deserialize(byte[] data, DirtyBy by) {
			try {
				_value = data.FromBytes(_value.GetType());
				SetDirty(by);
			} catch (Exception e) {
				throw new InvalidOperationException($"Failed to deserialize property '{_key}'", e);
			}
		}

		public override DirtyBy GetDirty()
			=> _dirty;

		public override void SetDirty(DirtyBy dirty) {
			if (dirty != DirtyBy.Local) return;
			_dirty = dirty;
		}

		public override string ToString()
			=> $"{GetType().Name}[Key={_key}, Value={_value}, Flags={_flags}, Dirty={_dirty}]";
	}
}

using System;
using Nox.CCK.Network;
using Nox.Entities;

namespace api.nox.relay {
	public class RawRelayProperty : RelayProperty {
		private readonly string        _key;
		private          object        _value;
		private          DirtyBy       _dirty;
		private          PropertyFlags _flags;

		public RawRelayProperty(RelayPlayer player, string key, object value) : base(player) {
			if (string.IsNullOrEmpty(key))
				throw new ArgumentException("Property key cannot be null or empty", nameof(key));
			_key = key;
			_value = value
				?? throw new ArgumentNullException(nameof(value), "Property value cannot be null");
		}

		public override string GetKey()
			=> _key;

		public override object GetValue()
			=> _value;

		public override PropertyFlags GetFlags()
			=> _flags;

		public override void SetValue(object value, DirtyBy by) {
			_value = value;
			SetDirty(by);
		}

		public override byte[] Serialize() {
			try {
				return _value.ToBytes();
			} catch (Exception e) {
				throw new InvalidOperationException($"Failed to serialize property '{_key}'", e);
			}
		}

		public override void Deserialize(byte[] data, DirtyBy by) {
			try {
				_value = data.FromBytes(_value.GetType());
				SetDirty(by);
			} catch (Exception e) {
				throw new InvalidOperationException($"Failed to deserialize property '{_key}'", e);
			}
		}

		public override DirtyBy GetDirty()
			=> _dirty;

		public override void SetDirty(DirtyBy dirty) {
			_dirty = dirty switch {
				DirtyBy.Local                  => DirtyBy.Local,
				DirtyBy.None or DirtyBy.Remote => DirtyBy.None,
				_                              => throw new ArgumentOutOfRangeException(nameof(dirty), dirty, null)
			};
		}

		public override string ToString()
			=> $"{GetType().Name}[Key={_key}, Value={_value}, Flags={_flags}, Dirty={_dirty}]";
	}
}

using System;
using Nox.CCK.Network;
using Nox.CCK.Utils;
using Nox.Entities;
using UnityEngine;
using Logger = Nox.CCK.Utils.Logger;
using Transform = Nox.CCK.Utils.Transform;
using UTransform = UnityEngine.Transform;

namespace api.nox.relay {
	/// <summary>
	/// Represents a part of a <see cref="RelayEntity"/>.
	/// </summary>
	public abstract class RelayPart : Transform, IPart {
		protected readonly RelayEntity Entity;
		private            DirtyBy     _dirty;

		protected RelayPart(RelayEntity entity)
			=> Entity = entity;

		/// <summary>
		/// Tries to get the GameObject associated by the implementation.
		/// </summary>
		/// <param name="go"></param>
		/// <param name="rigid"></param>
		/// <returns></returns>
		protected virtual bool TryGet(out UTransform go, out Rigidbody rigid) {
			go    = null;
			rigid = null;
			return false;
		}

		/// <summary>
		/// Get the ID.
		/// </summary>
		/// <returns></returns>
		public abstract ushort GetId();

		/// <summary>
		/// Try to get the position by the implementation.
		/// </summary>
		/// <param name="position"></param>
		/// <returns></returns>
		public bool TryGetPosition(out Vector3 position) {
			position = GetPosition();
			return Flags.HasFlag(TransformFlags.Position);
		}

		/// <summary>
		/// Try to get the rotation by the implementation.
		/// </summary>
		/// <param name="rotation"></param>
		/// <returns></returns>
		public bool TryGetRotation(out Quaternion rotation) {
			rotation = GetRotation();
			return Flags.HasFlag(TransformFlags.Rotation);
		}

		/// <summary>
		/// Try to get the scale by the implementation.
		/// </summary>
		public bool TryGetScale(out Vector3 scale) {
			scale = GetScale();
			return Flags.HasFlag(TransformFlags.Scale);
		}

		/// <summary>
		/// Try to get the velocity by the implementation.
		/// </summary>
		public bool TryGetVelocity(out Vector3 velocity) {
			velocity = GetVelocity();
			return Flags.HasFlag(TransformFlags.Velocity);
		}

		/// <summary>
		/// Try to get the angular velocity by the implementation.
		/// </summary>
		public bool TryGetAngularVelocity(out Vector3 angularVelocity) {
			angularVelocity = GetAngularVelocity();
			return Flags.HasFlag(TransformFlags.AngularVelocity);
		}

		void IPart.SetPosition(Vector3 position, DirtyBy markDirty) {
			if (Vector3.Distance(position, GetPosition()) < DefaultThreshold) return;
			SetPosition(position);
			SetDirty(markDirty);
		}

		void IPart.SetRotation(Quaternion rotation, DirtyBy markDirty) {
			if (Quaternion.Angle(rotation, GetRotation()) < DefaultThreshold) return;
			SetRotation(rotation);
			SetDirty(markDirty);
		}

		void IPart.SetScale(Vector3 scale, DirtyBy markDirty) {
			if (Vector3.Distance(scale, GetScale()) < DefaultThreshold) return;
			SetScale(scale);
			SetDirty(markDirty);
		}

		void IPart.SetVelocity(Vector3 velocity, DirtyBy markDirty) {
			if (Vector3.Distance(velocity, GetVelocity()) < DefaultThreshold) return;
			SetVelocity(velocity);
			SetDirty(markDirty);
			if (markDirty == DirtyBy.Remote && TryGet(out _, out var rigid) && rigid)
				rigid.linearVelocity = velocity;
		}

		void IPart.SetAngularVelocity(Vector3 angularVelocity, DirtyBy markDirty) {
			if (Vector3.Distance(angularVelocity, GetAngularVelocity()) < DefaultThreshold) return;
			SetAngularVelocity(angularVelocity);
			SetDirty(markDirty);
			if (markDirty == DirtyBy.Remote && TryGet(out _, out var rigid) && rigid)
				rigid.angularVelocity = angularVelocity;
		}

		public DirtyBy GetDirty()
			=> _dirty;

		public void SetDirty(DirtyBy by) {
			switch (by) {
				case DirtyBy.Remote:
					_dirty = DirtyBy.None;
					return;
				case DirtyBy.Local:
					_dirty = DirtyBy.Local;
					return;
				case DirtyBy.None:
					_dirty = DirtyBy.None;
					ResetPosition();
					ResetRotation();
					ResetScale();
					ResetVelocity();
					ResetAngularVelocity();
					return;
				default:
					throw new ArgumentOutOfRangeException(nameof(by), by, null);
			}
		}

		public void Update(float time) {
			if (!TryGet(out var transform, out _) || !transform)
				return;

			transform.GetPositionAndRotation(out var position, out var rotation);

			if (!IsSamePosition(position)) {
				var p   = GetPosition();
				var dis = Vector3.Distance(position, p);
				position = dis switch {
					> 10f     => p,
					<= 0.001f => p,
					_         => Vector3.Lerp(position, p, time)
				};
			}

			if (!IsSameRotation(rotation)) {
				var r   = GetRotation();
				var ang = Quaternion.Angle(rotation, r);
				rotation = ang switch {
					> 90f   => r,
					<= 0.1f => r,
					_       => Quaternion.Slerp(rotation, r, time)
				};
			}

			var scale = transform.localScale;
			if (!IsSameScale(scale)) {
				var s   = GetScale();
				var dis = Vector3.Distance(scale, s);
				scale = dis switch {
					> 10f     => s,
					<= 0.001f => s,
					_         => Vector3.Lerp(scale, s, time)
				};
				transform.localScale = scale;
			}

			transform.SetPositionAndRotation(position, rotation);
		}

		public override string ToString()
			=> $"{GetType().Name}[Id={GetId()}, EntityId={Entity.GetId()}, Dirty={GetDirty()}, Flags={Flags}]";
	}
}

